def greatest_common_divisor(a: int, b: int) -> int:
    """Return the nonnegative greatest common divisor of a and b."""
    a, b = abs(a), abs(b)
    while b:
        a, b = b, a % b
    return a

def is_nested(string):
    target = '[[]]'
    matched = 0
    for bracket in string:
        if bracket == target[matched]:
            matched += 1
            if matched == len(target):
                return True
    return False

