def file_name_check(file_name):
    if file_name.count('.') != 1:
        return 'No'
    name, extension = file_name.split('.')
    if not name or not ('a' <= name[0] <= 'z' or 'A' <= name[0] <= 'Z'):
        return 'No'
    if extension not in ('txt', 'exe', 'dll'):
        return 'No'
    if sum('0' <= char <= '9' for char in file_name) > 3:
        return 'No'
    return 'Yes'

